import{_ as e,o as t,c as s,Q as o}from"./chunks/framework.b67c47e6.js";const r="/assets/issues-view.3edb20be.svg",m=JSON.parse('{"title":"Issues Management","description":"","frontmatter":{},"headers":[],"relativePath":"guide/issues/index.md","filePath":"guide/issues/index.md","lastUpdated":1792316148000}'),a={name:"guide/issues/index.md"},i=o('<h1 id="issues-management" tabindex="-1">Issues Management <a class="header-anchor" href="#issues-management" aria-label="Permalink to &quot;Issues Management&quot;">​</a></h1><p>The Issues view provides a centralized overview of all production issues and quality control records across a project. Open it from the project menu: <strong>Production → Production Issues</strong>.</p><p>To see the issues of every project at once, use the <a href="#all-projects-at-once">company-wide list</a>.</p><nav class="table-of-contents"><ul><li><a href="#overview">Overview</a></li><li><a href="#issue-categories">Issue Categories</a></li><li><a href="#issue-fields">Issue Fields</a></li><li><a href="#creating-issues">Creating Issues</a></li><li><a href="#editing-and-deleting">Editing and Deleting</a></li><li><a href="#resolving-issues">Resolving Issues</a></li><li><a href="#sorting">Sorting</a></li><li><a href="#all-projects-at-once">All projects at once</a><ul><li><a href="#dates">Dates</a></li><li><a href="#filters">Filters</a></li></ul></li></ul></nav><p><img src="'+r+'" alt="Production Issues, with the detail of one issue open"></p><ol><li>The summary: all issues, and how many of each category.</li><li>The table. A tick in <strong>Status</strong> means the issue is solved.</li><li><strong>Edit issue</strong>, <strong>Solve issue</strong> and <strong>Delete</strong>, in the detail panel.</li></ol><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>At the top, a summary card shows:</p><ul><li>Total issue count</li><li>Breakdown by category: <strong>Quality Control Issue</strong> and <strong>Production Issue</strong></li></ul><p>Below the summary, a data table lists all issues of the project.</p><h2 id="issue-categories" tabindex="-1">Issue Categories <a class="header-anchor" href="#issue-categories" aria-label="Permalink to &quot;Issue Categories&quot;">​</a></h2><table><thead><tr><th>Category</th><th>Description</th></tr></thead><tbody><tr><td><strong>Quality Control Issue</strong></td><td>Issues related to product quality, compliance, or inspection findings. They appear in the <a href="/guide/reports/quality_control/">Quality Control Report</a>.</td></tr><tr><td><strong>Production Issue</strong></td><td>Problems encountered during the manufacturing process (delays, equipment, material defects). They appear in the <a href="/guide/reports/issues/">Issues Report</a>.</td></tr></tbody></table><h2 id="issue-fields" tabindex="-1">Issue Fields <a class="header-anchor" href="#issue-fields" aria-label="Permalink to &quot;Issue Fields&quot;">​</a></h2><table><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Title</strong></td><td>Short description of the issue. Click it to open the issue detail.</td></tr><tr><td><strong>Text</strong></td><td>Detailed explanation of the problem.</td></tr><tr><td><strong>Category</strong></td><td>Quality control or production issue.</td></tr><tr><td><strong>Constructible</strong></td><td>The assembly or module affected, with its position in the batch.</td></tr><tr><td><strong>Author</strong></td><td>Who reported the issue: their employee alias, or their username when they have none.</td></tr><tr><td><strong>Created</strong></td><td>When the issue was reported.</td></tr><tr><td><strong>Status</strong></td><td>Open or solved. The table shows a check when the issue is solved.</td></tr><tr><td><strong>Pictures</strong></td><td>Optional photos or files attached to the issue.</td></tr></tbody></table><p>The issue detail also shows the design and its revision, and the engineering contact of the project when one is set.</p><h2 id="creating-issues" tabindex="-1">Creating Issues <a class="header-anchor" href="#creating-issues" aria-label="Permalink to &quot;Creating Issues&quot;">​</a></h2><p>Issues are created in the <a href="/guide/viewer/#issues">3D Viewer</a>: while viewing a constructible, click <strong>New issue</strong> (the speech bubble with a <strong>+</strong>) to report a problem directly from the production floor. You can attach the parts selected in the 3D view and pictures. An issue marked as <em>hot</em> shows in the viewer, in the <strong>Hot issues</strong> dialog of the panel and of the other units of the same design.</p><h2 id="editing-and-deleting" tabindex="-1">Editing and Deleting <a class="header-anchor" href="#editing-and-deleting" aria-label="Permalink to &quot;Editing and Deleting&quot;">​</a></h2><p>Each row has <strong>Solve issue</strong> and <strong>Edit issue</strong> (title, text and category). <strong>Delete</strong> is in the <strong>⋮</strong> menu and asks for confirmation. A solved issue keeps the Solve button, greyed out. The same actions are in the issue detail. See <a href="/guide/#row-buttons">Row buttons</a>.</p><h2 id="resolving-issues" tabindex="-1">Resolving Issues <a class="header-anchor" href="#resolving-issues" aria-label="Permalink to &quot;Resolving Issues&quot;">​</a></h2><p>To close an issue:</p><ol><li>Click <strong>Solve issue</strong> on its row or in the issue detail.</li><li>Select the design <strong>Revision</strong> in which the issue was solved.</li><li>Add a <strong>Comment</strong> explaining how it was fixed.</li><li>Click <strong>Submit</strong>.</li></ol><p>The issue is then marked as solved, and its detail shows the revision and the solving comment.</p><h2 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h2><p>Click a column header to sort the table by title, constructible, category, author, creation date or status.</p><h2 id="all-projects-at-once" tabindex="-1">All projects at once <a class="header-anchor" href="#all-projects-at-once" aria-label="Permalink to &quot;All projects at once&quot;">​</a></h2><p>With <strong>All projects</strong> selected, the left menu has a <strong>Production Issues</strong> entry under <strong>Production Schedule</strong>. It lists the issues of every project of the company, newest first.</p><h3 id="dates" tabindex="-1">Dates <a class="header-anchor" href="#dates" aria-label="Permalink to &quot;Dates&quot;">​</a></h3><p>The list shows the issues <strong>created</strong> between two dates. When you open it, it shows the current year. Change <strong>From</strong> or <strong>To</strong>, or tap <strong>This year</strong>, <strong>Last year</strong> or <strong>Last 90 days</strong>, and the list loads again by itself. Leave a date empty to have no limit on that side.</p><p>An open issue created before <strong>From</strong> is not in the list. To see every open issue, pick a wider range.</p><h3 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h3><p>The other filters work on the issues already loaded, so they apply at once:</p><table><thead><tr><th>Filter</th><th>Shows</th></tr></thead><tbody><tr><td><strong>Production Issue</strong> / <strong>Quality Control Issue</strong></td><td>the issues of the categories that are on. Both are on at first.</td></tr><tr><td><strong>All</strong> / <strong>Open</strong> / <strong>Solved</strong></td><td>the issues in that state.</td></tr><tr><td><strong>Only hot issues</strong></td><td>the issues marked as hot, the ones shown in the viewer.</td></tr><tr><td><strong>Search</strong></td><td>the issues whose title or text contains what you type.</td></tr><tr><td><strong>Super project</strong></td><td>the issues of the projects in those super projects. It also narrows the <strong>Projects</strong> list.</td></tr><tr><td><strong>Projects</strong></td><td>the issues of those projects.</td></tr><tr><td><strong>Production Line</strong></td><td>the issues of panels whose batch is on those lines. <strong>No line</strong> is for issues on a design only, or on a panel whose batch has no line.</td></tr><tr><td><strong>Author</strong></td><td>the issues reported by those people. <strong>Deleted account</strong> is for the issues whose author&#39;s account no longer exists.</td></tr></tbody></table><p>Each list only offers what the loaded issues have, so no choice leaves the table empty. <strong>Clear</strong> resets every filter but the dates.</p><p>The cards above the table count what the filters show: the issues shown out of those loaded, how many are open, solved and hot, and how many of each category.</p><p>The table adds two columns to the project one: <strong>Project</strong>, with its super project under it, and <strong>Line</strong>. Click a title to open the issue, and the constructible to open it in its project. The dates and filters are kept in the page address, so you can bookmark a filtered list or send it to a colleague.</p><p>On a phone, the dates and filters are in the <strong>Filters</strong> button, which shows how many filters are on.</p>',37),n=[i];function l(d,h,u,g,c,p){return t(),s("div",null,n)}const b=e(a,[["render",l]]);export{m as __pageData,b as default};
